files.CustomersForm.tsx:
import { createSignal, Show } from "solid-js";

export default function CustomersForm(props: { onAdd: (name: string, amount: number) => void }) {
  const [name, setName] = createSignal("");
  const [amount, setAmount] = createSignal("");
  const [error, setError] = createSignal("");

  function submit() {
    if (!name().trim()) {
      setError("Nombre requerido");
      return;
    }
    setError("");
    props.onAdd(name(), Number(amount()) || 0);
    setName("");
    setAmount("");
  }

  return (
    <div class="flex flex-col gap-1">
    <div class="flex gap-2">
      <input placeholder="Nombre" value={name()} onInput={(e) => { setName(e.currentTarget.value); if (error()) setError(""); }} />
      <input placeholder="Saldo" type="number" value={amount()} onInput={(e) => setAmount(e.currentTarget.value)} />
      <button class="primary" onClick={submit}>Agregar</button>
    </div>
    <Show when={error()}>
      <span class="text-red-600 text-sm">{error()}</span>
    </Show>
    </div>
  );
}

